import { useForm, useWatch } from "react-hook-form"
import Input from "../../Input/Input";
import Tarjeta from "../../ComponentesFormulario/Tarjeta/Tarjeta";
import Boton from '../../Boton/Boton';
import Selector from "../../Selector/Selector";
import { useState, useEffect } from 'react'
import { toast } from "sonner";
import { useValidarSesion } from "../../../hooks/useValidarSesion";
import { useBusqueda } from "../../../hooks/useBusqueda";
import { p } from "framer-motion/client";


export default function TransferirProducto({ onGuardar, sucursalOrigen }) {

    //Recupero informacion del usuario logueado
    const { token } = useValidarSesion(); // obtener el token desde Zustand

    /////// HOOK FORM
    const { register, handleSubmit, formState: { errors }, reset, control, setValue } = useForm({
        defaultValues: {
            tipo_busqueda: "Nombre",
        }
    });

    //USE WATCH PARA SABER QUE TIPO DE BUSQUEDA SE ESTA REALIZANDO, POR CODIGO O NOMBRE
    const tipoBusqueda = useWatch({ control, name: "tipo_busqueda" });

    //USE WATCH PARA OBTENER LA CANTIDAD A TRANSFERIR E IR RESTANDO A LA CANTIDAD ACTUAL
    const cantidadTransferir = useWatch({ control, name: "cantidad" });


    //CON EL SIGUIENTE FETCH OBTENGO DATOS DEL PRODUCTO SELECCIONADO y luego lo guardo en elemento

    const id_producto = useWatch({ control, name: "id_producto" });
    const [elemento, setElemento] = useState(null);



    useEffect(() => {
        if (!id_producto) return;

        const obtenerProducto = async () => {
            try {
                const respuestaProducto = await fetch(
                    `${import.meta.env.VITE_API_BASE_URL}/api/producto/${id_producto}/mostrar2`,
                    {
                        method: 'POST',
                        headers: {
                            'Content-Type': 'application/json',
                            'Accept': 'application/json',
                            'Authorization': `Bearer ${token}`,
                        },
                        body: JSON.stringify({
                            id_sucursal: sucursalOrigen, // sucursal del usuario
                        }),
                    }
                );

                if (!respuestaProducto.ok) {
                    throw new Error(`Error ${respuestaProducto.status}`);
                }

                const datos = await respuestaProducto.json();
                setElemento(datos);
            } catch (error) {
                console.error('Error en la solicitud:', error);
            }
        };

        obtenerProducto(); // llamamos la función async
    }, [id_producto]);





    //USAR HOOK DE USEBUSQUEDA PARA BUSCAR PRODUCTO
    const {
        sugerencias: productoSugerencias,
        terminoBusqueda: buscarProducto,
        setTerminoBusqueda: setBuscarProducto,
        seleccionado: productoSeleccionado,
        manejarSeleccion: seleccionarProducto
    } = useBusqueda('producto', tipoBusqueda, setValue);




    /////// CREACION POST DE TRANSFERENCIA
    const onSubmit = async (data) => {

        // Agregamos sucursalOrigen al objeto data
        const payload = {
            ...data,
            sucursalOrigen: sucursalOrigen
        };
        console.log(payload);
        setCargando(true);
        try {
            const respuesta = await fetch(`${import.meta.env.VITE_API_BASE_URL}/api/producto/transferir`, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    'Accept': 'application/json',
                    'Authorization': `Bearer ${token}`
                },
                body: JSON.stringify(payload),
            });

            // Intentamos leer siempre la respuesta (aunque haya error)
            const dataRespuestaTransferencia = await respuesta.json().catch(() => ({}));

            if (respuesta.ok) {
                reset();

                toast.success("Stock transferido.", { className: "__toaster_success" })
                onGuardar();
            } else {
                console.log(payload);
                const mensajeError = dataRespuestaTransferencia?.error || "Error al transferir stock.";
                toast.error(mensajeError, { className: "__toaster_error" });
                return;
            }
        } catch (error) {
            console.error('Error en la solicitud:', error);
            toast.error("Error inesperado al transferir.", { className: "__toaster_error" });
        } finally {
            setCargando(false);
        }
    };

    //////////// BUSCA SUCURSALES EN EL BACKEND
    const [sucursales, setSucursales] = useState([]);

    useEffect(() => {
        if (!sucursalOrigen) return;

        const obtenerDatos = async () => {
            try {
                const respuesta = await fetch(`${import.meta.env.VITE_API_BASE_URL}/api/sucursal`);
                const datos = await respuesta.json();
                // Filtrar para excluir la sucursal de origen
                const sucursalesFiltradas = datos.filter(
                    sucursal => sucursal.id_sucursal !== sucursalOrigen
                );
                setSucursales(sucursalesFiltradas);
            } catch (error) {
                console.log(error);
            }
        };

        obtenerDatos();
    }, [sucursalOrigen]);

    console.log(sucursales);
    console.log(productoSeleccionado);

    /////////// ESTADO PARA SABER CUANDO SE ESTA CARGANDO (SE ESTAN TRAYENDO LOS DATOS)
    const [cargando, setCargando] = useState(false);

    ////// LAYOUT
    return (
        <>
            {cargando && <div className='__cargando_fondo'><div className="__cargando"></div> </div>}
            <form onSubmit={handleSubmit(onSubmit)} style={{ display: "flex", flexDirection: "column" }} >
                <div style={{ display: "flex", gap: "50px" }}>
                    <div style={{ flexDirection: "column", display: "flex", gap: "20px", flex: 1, marginLeft: "20px" }} >
                       { /*<Tarjeta descripcion="Producto" forid="producto" >
                            <Input
                                title="Ingrese el producto a transferir"
                                tipo="search"
                                id="producto"
                                placeholder="Buscar"
                                value={productoSeleccionado || buscarProducto}
                                onChange={(e) => {
                                    setBuscarProducto(e.target.value);
                                    if (productoSeleccionado) seleccionarProducto(null);
                                }}


                            />
                            {productoSugerencias.length > 0 && (
                                <ul className="__sugerencias">
                                    {productoSugerencias.map((producto) => (
                                        <li key={producto.id_producto} onClick={() => seleccionarProducto(producto)}>
                                            {tipoBusqueda === "Nombre" ? producto.producto : producto.codigo}

                                        </li>
                                    ))}
                                </ul>
                            )}
                        </Tarjeta>*/}
                        <Tarjeta descripcion="Buscar por" forid="tipoBusqueda">
                            <Selector opciones={[{ label: "Nombre", value: "Nombre" }, { label: "Codigo", value: "Codigo" }]} id="tipoBusqueda"
                                opcionDefecto
                                {...register("tipo_busqueda")}
                            >
                            </Selector>
                        </Tarjeta>

                        <Tarjeta descripcion="Cantidad Actual" forid="stock" >
                            <Input
                                tipo="number"
                                id="stock"
                                placeholder={elemento ? elemento.stock : "0"}
                                deshabilitado
                            > </Input>
                        </Tarjeta>

                    </div>
                    <div style={{ flexDirection: "column", display: "flex", gap: "20px", flex: 1 }}>
                        <Tarjeta descripcion="Cantidad a Transferir" forid="cantidad" mensajeError={errors.cantidad?.message}>
                            <Input
                            title="Ingrese la cantidad a transferir"
                                tipo="number"
                                id="cantidad"
                                placeholder="0"
                                {...register("cantidad", {
                                    required: {
                                        value: true,
                                        message: `Ingrese cantidad del Producto`
                                    },
                                    validate: (value) => {
                                        if (elemento && (value > 0 && value <= (elemento.stock))) return true;
                                        else return elemento ? `Ingrese una cantidad entre '0' y ${elemento.stock} unidades` :
                                            "Seleccione un producto válido";
                                    },
                                })}
                            />
                        </Tarjeta>
                    </div>
                    <div style={{ flexDirection: "column", display: "flex", gap: "20px", flex: 1, marginRight: "50px" }}>
                       <Tarjeta descripcion="Sucursal Destino" forid="sucursalDestino" mensajeError={errors.sucursalDestino?.message}>
                            <Selector
                                title="Seleccione la sucursal destino"
                                opciones={sucursales
                                    .filter(suc => suc.id_sucursal !== sucursalOrigen) // excluye la sucursal actual
                                    .map(suc => ({ label: suc.nombre, value: suc.id_sucursal }))
                                }
                                {...register("sucursalDestino", { required: { value: true, message: "Ingrese Sucursal Destino" } })}
                            />
                        </Tarjeta>
                    </div>
                </div >
                <div style={{ alignItems: "center", display: "flex", justifyContent: "center", marginTop: "20px" }}>
                    <Boton descripcion='Transferir' habilitado submit></Boton>
                </div>
            </form>
        </>

    )

}