import TablaConPaginacion from "../../Componentes/TablaConPaginacion/TablaConPaginacion";
import PanelProductos from '../../Componentes/Paneles/PanelProductos/PanelProductos'
import PlantillaPages from '../../Componentes/PlantillaPages/PlantillaPages'
import Pestanias from "../../Componentes/Pestanias/Pestanias";
import Boton from "../../Componentes/Boton/Boton";
import ModificarProducto from "../../Componentes/Formularios/ModificarProducto/ModificarProducto";
import Modal from "../../Componentes/Modal/Modal";
import NuevoProducto from "../../Componentes/Formularios/NuevoProducto/NuevoProducto";
import { useEffect, useState } from 'react'
import columnas from '../../Datos_Pruebas/Columnas_Productos.json'
import columnasAlertaStock from '../../Datos_Pruebas/Columnas_AlertaStock.json'
import { useRef } from "react";
import { useValidarSesion } from "../../hooks/useValidarSesion";
import TransferirProducto from "../../Componentes/Formularios/TransferirProducto/TransferirProducto";
import { set } from "react-hook-form";



export default function Productos({ }) {


  /////////// ESTADO PARA SABER CUANDO SE ESTA CARGANDO (SE ESTAN TRAYENDO LOS DATOS)
  const [cargando, setCargando] = useState(false);


  const { storeCargado, token, usuario } = useValidarSesion(); // obtener el token desde Zustand



  //BOOLEANO PARA PREGUNTAR SI EL USUARIO TIENE PERMISO DE CREAR PRODUCTO
  const permisoCrearProducto = usuario?.permisos?.some(
    (permiso) => permiso.nombrePermiso === 'crear producto'
  ) ||
    usuario?.permisos_extra?.some(
      (permiso) => permiso.nombrePermiso === 'crear producto'
    );

  //BOOLEANO PARA PREGUNTAR SI EL USUARIO TIENE PERMISO DE MOFICIAR PRODUCTO
  const permisoModificarProducto = usuario?.permisos?.some(
    (permiso) => permiso.nombrePermiso === 'modificar producto'
  ) ||
    usuario?.permisos_extra?.some(
      (permiso) => permiso.nombrePermiso === 'modificar producto'
    );




  //BOOLEANO PARA PREGUNTAR SI EL USUARIO TIENE PERMISO DE MODIFICAR STOCK (POR DEVOLUCION O ROMPIMIENTO)
  const permisoModificarStock = usuario?.permisos?.some(
    (permiso) => permiso.nombrePermiso === 'modificar stock'
  ) ||
    usuario?.permisos_extra?.some(
      (permiso) => permiso.nombrePermiso === 'modificar stock'
    );


  //BOOLEANO PARA PREGUNTAR SI EL USUARIO TIENE PERMISO DE CREAR PRODUCTO y con ello mostrr o no algunas opciones
  const permisoTransferirProducto =
    usuario?.permisos?.some(
      (permiso) => permiso.nombrePermiso === 'transferir producto'
    ) ||
    usuario?.permisos_extra?.some(
      (permiso) => permiso.nombrePermiso === 'transferir producto'
    );


  //BOOLEANO DEFINE SI ES SUPERADMIN
  const esSuperAdmin = usuario?.rol?.[0]?.nombreRol === "superadmin";

  //ESTADO PARA DETERMINAR LA SUCURSAL
  const [idSucursalSeleccionada, setIdSucursalSeleccionada] = useState(
    esSuperAdmin ? null : usuario?.sucursal?.[0]?.id_sucursal || null
  );



  //////////// BUSCA CATEGORIAS Y MARCAS EN EL BACKEND
  const [categorias, setCategorias] = useState([]);
  const [marcas, setMarcas] = useState([]);


  const obtenerDatos = () => {
  fetch(`${import.meta.env.VITE_API_BASE_URL}/api/categoria`)
      .then(respuesta => respuesta.json())
      .then(datos => setCategorias(datos))
      .catch(e => console.log(e));
  fetch(`${import.meta.env.VITE_API_BASE_URL}/api/marca`)
      .then(respuesta => respuesta.json())
      .then(datos => setMarcas(datos))
      .catch(e => console.log(e));
  };

  useEffect(() => {
    obtenerDatos();
  }, []);

  ////  MANEJA MODAL ALERTAS DE STOCK Y OBTIENE ALERTAS DE STOCK
  const [alertasStockBajo, setAlertasStockBajo] = useState([]);

  const [modalAlertasStock, setModalAlertasStock] = useState(false);
  const manejaModalAlertasStock = () => {
    setModalAlertasStock(!modalAlertasStock);
    obtieneAlertasStockBajo();
  }

  const obtieneAlertasStockBajo = async () => {
    setCargando(true);
    try {
  const respuesta = await fetch(`${import.meta.env.VITE_API_BASE_URL}/api/alerta-stock/todas`, {
        method: 'GET',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        }
      });

      if (!respuesta.ok) {
        console.error('Error al obtener alertas de stock bajo');
        return;
      }
      const datos = await respuesta.json();
      const datosTransformadosStock = datos.map(item => ({
                Producto: item.producto,
                Stock_Actual: item.stock_actual,
                Alerta_Minima: item.alerta_minima,
                Sucursal: item.nombre,
               
            }));
      setAlertasStockBajo(datosTransformadosStock);
    } catch (error) {
      console.error('Error en la solicitud:', error);
    } finally {
      setCargando(false);
    }
  };




  /////// FUNCION QUE SE LE PASA AL PANEL PARA RECUPERAR LOS DATOS FILTRADOS
  const [datos, setDatos] = useState([]);
  const obtieneDatosFiltrados = (datosFiltrados) => {
    setDatos(datosFiltrados);
  };

  /////////////////////////MODAL NUEVO PRODUCTO
  const [modalNuevoProducto, setModalNuevoProducto] = useState(false); // Abre o cierra el modal nuevo prodcuto

  const manejaModalNuevoProducto = () => {
    setModalNuevoProducto(!modalNuevoProducto);
    if (modalNuevoProducto) {
      obtenerDatos();
      actualizarDatos();
    }
  };

  //////////////////MODAL TRANSFERIR PRODUCTO

  const [modalTransferir, setModalTransferir] = useState(false); // Abre o cierra el modal transferir producto

  const manejaModalTransferir = () => {
    setModalTransferir(!modalTransferir);
    if (modalTransferir) {
      obtenerDatos();
      actualizarDatos();
    }
  };



  //////////////SELECCION DE PRODUCTO Y MODAL MODIFICAR PRODUCTO
  const [elementoSeleccionado, setElementoSeleccionado] = useState(null);
  const manejarSeleccion = (elemento) => {
    setElementoSeleccionado(elemento);
  };

  const [modalModifProducto, setModifProducto] = useState(false); // Abre o cierra el modal nueva sucursal
  const manejaModifProducto = () => {
    setModifProducto(!modalModifProducto);

    if (modalModifProducto) {  //si el modal estaba abierto, al cerrarse se setea a null el elmento seleccionado
      setElementoSeleccionado(null);
      setElemento(null);
      actualizarDatos();
    }
  };

  ///////////////BUSCA EN BACKEND ELEMENTO SELECCIONADO
  const [elemento, setElemento] = useState(null);
  /*
    useEffect(() => {
      if (elementoSeleccionado) {
  fetch(`${import.meta.env.VITE_API_BASE_URL}/api/producto/${elementoSeleccionado.id_producto}`)
          .then(respuesta => respuesta.json())
          .then(datos => setElemento(datos))
          .catch(e => console.log(e));
      }
    }, [elementoSeleccionado]);//Cuando cambie elementoSeleccionado se ejecuta el efecto*/

  useEffect(() => {
    if (!elementoSeleccionado) return;

    const obtenerProducto = async () => {
      try {
        const respuestaProducto = await fetch(
          `${import.meta.env.VITE_API_BASE_URL}/api/producto/${elementoSeleccionado.id_producto}/mostrar2`,
          {
            method: 'POST',
            headers: {
              'Content-Type': 'application/json',
              'Accept': 'application/json',
              'Authorization': `Bearer ${token}`,
            },
            body: JSON.stringify({
              id_sucursal: idSucursalSeleccionada, // sucursal del usuario
            }),
          }
        );

        if (!respuestaProducto.ok) {
          throw new Error(`Error ${respuestaProducto.status}`);
        }

        const datos = await respuestaProducto.json();
        setElemento(datos);
      } catch (error) {
        console.error('Error en la solicitud:', error);
      }
    };

    obtenerProducto(); // llamamos la función async
  }, [elementoSeleccionado]);





  ////REFERENCIA A PANEL PRODUCTOS

  const panelProductosRef = useRef();

  const actualizarDatos = () => {
    if (panelProductosRef.current) {
      panelProductosRef.current.actualizarDatos();
    }
  }




  ////////SE CREA OBJETO PUNTERO TIPO USEREF PARA PASARLE LA FUNCION DE OBTENER MARCAS Y CATEGORIAS A SUS HIJOS
  const actualizarCategoriasYMarcas = useRef(() => {
    obtenerDatos(); //los hijs al ejecutar actualizarCategoriasYMarcas, ejecutaran obtenerDatos()
  })




  const manejaCargando = ((valor) => {
    setCargando(valor);
  });

  //  PROTECCIÓN: si todavia no se cargo el store ni usuario, no reendreizar nada
  if (!storeCargado || !usuario || !token) {
    return <div className="__cargando_modal"></div>;
  }

console.log('alertasStockBajo:', alertasStockBajo);

  //LAYOUT

  const header = <PanelProductos
    ref={panelProductosRef}
    categorias={categorias}
    marcas={marcas}
    onDatosFiltrados={obtieneDatosFiltrados}
    onManejaCargando={manejaCargando}
    esSuperAdmin={esSuperAdmin}
    onSeleccionarSucursal={setIdSucursalSeleccionada} //callback para recuperar sucursal del panel si se trata de un superadmin
    token={token}
  >
  </PanelProductos>


  const main = <TablaConPaginacion columnas={columnas} datos={datos} itemsPorPagina={6}
    itemsPorPaginaOpcional onElementoSeleccionado={manejarSeleccion} cargando={cargando}>
  </TablaConPaginacion>

  const navigation = <Pestanias></Pestanias>

  const footer = <div style={{ display: "flex" }}>
    {permisoCrearProducto && <Boton descripcion={"NUEVO"} onClick={manejaModalNuevoProducto} habilitado title="Cargar nuevo producto"></Boton>}
    {permisoModificarProducto || permisoModificarStock ? <Boton descripcion={"VER"} onClick={manejaModifProducto} habilitado={elementoSeleccionado} title="Ver detalles"></Boton> : null}
    {permisoTransferirProducto && <Boton descripcion={"TRANSFERIR"} onClick={manejaModalTransferir} habilitado title="Transferir existencias a otra sucursal"></Boton>}
    {esSuperAdmin && <Boton descripcion={"ALERTAS DE STOCK"} onClick={manejaModalAlertasStock} habilitado title="Ver alertas globales de stock"></Boton>}
    <Modal visible={modalModifProducto} titulo="Detalles del Producto" funcion={manejaModifProducto} anchura={"800px"} >
      {!elemento ? (
        <div className="__cargando_modal">Cargando producto...</div>
      ) : (
        <ModificarProducto
          autocompletar={elemento}
          onGuardar={manejaModifProducto}
          categorias={categorias}
          marcas={marcas}
          token={token}
          id_sucursal={idSucursalSeleccionada}
          permisoModificarProducto={permisoModificarProducto}
          permisoModificarStock={permisoModificarStock}
        />
      )}
    </Modal>
    <Modal visible={modalNuevoProducto} titulo="Cargar Nuevo Producto" funcion={manejaModalNuevoProducto} anchura={"800px"} >
      <NuevoProducto categorias={categorias}
        onGuardar={manejaModalNuevoProducto}
        marcas={marcas}
        actualizarCategoriasYMarcas={actualizarCategoriasYMarcas} //paso la fucnion referencia
        token={token}
        id_sucursal={idSucursalSeleccionada}
      ></NuevoProducto>
    </Modal>
    <Modal visible={modalTransferir} titulo="Transferir Producto" funcion={manejaModalTransferir} anchura={"700px"} >
      {idSucursalSeleccionada &&
        <TransferirProducto sucursalOrigen={idSucursalSeleccionada} onGuardar={manejaModalTransferir}></TransferirProducto>
      }
    </Modal>
    <Modal visible={modalAlertasStock} titulo="Alertas de Stock Bajo" funcion={manejaModalAlertasStock} anchura={"900px"} >
        <TablaConPaginacion columnas={columnasAlertaStock} datos={alertasStockBajo} itemsPorPagina={5} itemsPorPaginaOpcional></TablaConPaginacion>
      </Modal>
  </div>

  return <PlantillaPages
    header={header}
    navigation={navigation}
    main={main}
    footer={footer}
    nombreUsuario={usuario?.nombre}
    apellidoUsuario={usuario?.apellido}
    sucursal={usuario?.sucursal?.[0]?.nombreSucursal}
    id_sucursal={idSucursalSeleccionada}
    rol={usuario?.rol?.[0]?.nombreRol}
    esSuperAdmin={esSuperAdmin}
    token={token}
  />;






}