import { useForm } from "react-hook-form"
import Input from "../../Input/Input";
import Tarjeta from "../../ComponentesFormulario/Tarjeta/Tarjeta";
import Boton from "../../Boton/Boton";
import Selector from "../../Selector/Selector";
import '../NuevoProducto/NuevoProducto.css';
import './ModificarProducto.css';
import restar from '../../../assets/eliminar.png'
import sumar from '../../../assets/mas.png'
import { useState, useEffect } from 'react'
import { toast } from "sonner";
import no_encontrado from "../../../assets/no_encontrado.png";
import { useUsuarioStore } from "../../../store/Usuario";

export default function ModificarProducto({ autocompletar, onGuardar, categorias, token, permisoModificarProducto, permisoModificarStock, id_sucursal, marcas }) {




    const { register, handleSubmit, formState: { errors }, reset, setValue } = useForm({
        defaultValues: {    //constante que devuleve todo lo del form

            codigo: autocompletar.codigo,
            producto: autocompletar.producto,
            costo: autocompletar.costo,
            alerta_minima: autocompletar.alerta_minima,
            id_categoria: autocompletar.id_categoria,
            id_marca: autocompletar.id_marca


        }
    });


    //PARA MENEJAR MODIFICACION DE IMAGEN
    // Función para construir URL de imagen (acepta rutas relativas y absolutas)
    const construirUrlImagen = (ruta) => {
        if (!ruta) return no_encontrado;
        // Si ya es URL absoluta, devolverla tal cual
        if (ruta.startsWith('http://') || ruta.startsWith('https://') || ruta.startsWith('//')) {
            return ruta;
        }
        // Si es ruta relativa (p. ej. /storage/...), prefijar con la base de la API definida en .env
        return `${import.meta.env.VITE_API_BASE_URL}${ruta}`;
    };

    // Estados para manejar la imagen
    const [imagenActual, setImagenActual] = useState(autocompletar.foto_url ? construirUrlImagen(autocompletar.foto_url) : no_encontrado);
    const [nuevaImagen, setNuevaImagen] = useState(null);
    const [archivoImagen, setArchivoImagen] = useState(null);
    const [mostrarInputFile, setMostrarInputFile] = useState(false);
    const [imagenEliminada, setImagenEliminada] = useState(false);

    // Funciones para manejo de imágenes 
    const manejarCambioImagen = (e) => {
        const archivo = e.target.files[0];
        if (archivo) {
            setArchivoImagen(archivo);
            setImagenEliminada(false);
            const reader = new FileReader();
            reader.onloadend = () => {
                setNuevaImagen(reader.result);
            };
            reader.readAsDataURL(archivo);
        }
        setMostrarInputFile(false);
    };

    const activarCambioImagen = () => {
        setMostrarInputFile(true);
        setNuevaImagen(null);
        setArchivoImagen(null);
        setImagenEliminada(false);
    };

    const cancelarCambioImagen = () => {
        setNuevaImagen(null);
        setArchivoImagen(null);
        setMostrarInputFile(false);
        setImagenEliminada(false);
    };

    const eliminarImagenActual = () => {
        setImagenActual(no_encontrado);
        setNuevaImagen(null);
        setArchivoImagen(null);
        setImagenEliminada(true);
        setMostrarInputFile(false);
    };


    const [modificar, setModificar] = useState(false); // Estado que Habilita la modificacion del producto

    const [cant, setCant] = useState(autocompletar.stock)

    const [modCant, setModCant] = useState(false);

    const [cantidadModificada, setCantidadModificada] = useState(0);


    const manejaModificacion = () => {
        setModificar(!modificar);
    };

    const disminuyeCant = () => {
        if (!modCant) setModCant(true);
        if (cant > 0) {
            setCant(cant - 1);
            setCantidadModificada(cantidadModificada - 1);
        }
    };

    const aumentaCant = () => {
        if (!modCant) setModCant(true);
        setCant(cant + 1);
        setCantidadModificada(cantidadModificada + 1);
    };




    const onSubmit = async (data) => {
        setCargando(true);
        console.log(data);
        try {
            const productoUrl = `${import.meta.env.VITE_API_BASE_URL}/api/producto/${autocompletar.id_producto}`;
            // Crear FormData para enviar archivo
            const formData = new FormData();
            formData.append('codigo', data.codigo);
            formData.append('producto', data.producto);
            formData.append('alerta_minima', data.alerta_minima);
            formData.append('costo', data.costo);
            formData.append('id_categoria', data.id_categoria);
            formData.append('id_marca', data.id_marca);
            formData.append('_method', 'PUT'); // Para simular método PUT con FormData

            // Agregar nueva imagen si existe
            if (archivoImagen) {
                formData.append('foto', archivoImagen);
            } else if (imagenEliminada) {
                formData.append("eliminar_foto", "true");
            }
            // Paso 1: Busca y actualiza producto
            const respuestaProducto = await fetch(productoUrl, {
                method: 'POST',
                headers: {
                    'Accept': 'application/json',
                    'Authorization': `Bearer ${token}`
                },
                body: formData,
            });

            // Intentamos leer siempre la respuesta (aunque haya error)
            const dataRespuestaProducto = await respuestaProducto.json().catch(() => ({}));

            if (!respuestaProducto.ok) {
                const mensajeError = dataRespuestaProducto?.error || "Error al modificar el producto.";
                toast.error(mensajeError, { className: "__toaster_error" });
                return;
            }


            // Paso 2: Crear el registro en la tabla `stock`
            const stockData = {
                cantidad: cantidadModificada,  // Usamos la cantidad del formulario
                tipo: "Manual",
                observaciones: data.observaciones || "Modificacion de stock",
                id_producto: autocompletar.id_producto,  // Usamos el id_producto del producto recién creado
                id_sucursal: id_sucursal
            };


            const respuestaStock = await fetch(`${import.meta.env.VITE_API_BASE_URL}/api/stock`, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify(stockData),
            });

            if (!respuestaStock.ok) {
                console.error('Error al crear el registro en stock');
                toast.error("Error al crear el registro en stock.", { className: "__toaster_error" });
                return;
            }

            const stockCreado = await respuestaStock.json();
            console.log('Registro en stock creado:', stockCreado);




            toast.success("Producto modificado correctamente.", { className: "__toaster_success" });
            reset(); // Resetea el formulario solo después de que ambas operaciones fueron exitosas
            setModificar(false);
            onGuardar();

            //resetaer imgen
                if (dataRespuestaProducto?.producto) {
                    // Si el backend devuelve foto_url, usarla, sino usar no_encontrado
                    const nuevaUrl = dataRespuestaProducto.producto.foto_url
                        ? construirUrlImagen(dataRespuestaProducto.producto.foto_url)
                        : no_encontrado;
                    setImagenActual(nuevaUrl);
                }

            setNuevaImagen(null);
            setArchivoImagen(null);
            setMostrarInputFile(false);
            setImagenEliminada(false);

        } catch (error) {
            console.error('Error en la solicitud:', error);
            toast.error("Error inesperado al modficar el producto.", { className: "__toaster_error" });
        } finally {
            setCargando(false);
        }

    };








    /////////// ESTADO PARA SABER CUANDO SE ESTA CARGANDO (SE ESTA MODIFICANDO)
    const [cargando, setCargando] = useState(false);



    ///////LAYOUT

    return (
        <>
            {cargando && <div className='__cargando_fondo'><div className="__cargando"></div> </div>}
            <form onSubmit={handleSubmit(onSubmit)} className="__formulario_modificar_producto">
                <div className="__cuerpo_nuevo_producto">
                    <div className="__columna_1">
                        <Tarjeta descripcion="Codigo" forid="codigo" mensajeError={errors.codigo?.message}>
                            <Input
                                tipo="text"
                                deshabilitado={(permisoModificarStock && !permisoModificarProducto) ? true : !modificar}
                                id="codigo"
                                {...register("codigo", { required: { value: true, message: "Ingrese un codigo de Producto" } })}
                            > </Input>
                        </Tarjeta>
                        <Tarjeta descripcion="Producto" forid="producto" mensajeError={errors.producto?.message}>
                            <Input
                                tipo="text "
                                id="producto"
                                deshabilitado={(permisoModificarStock && !permisoModificarProducto) ? true : !modificar}
                                {...register("producto", { required: { value: true, message: "Ingrese nombre del Producto" } })}
                            > </Input>
                        </Tarjeta>
                        <Tarjeta descripcion="Costo" forid="costo" mensajeError={errors.costo?.message}>
                            <Input
                                tipo="costo"
                                id="costo"
                                deshabilitado={(permisoModificarStock && !permisoModificarProducto) ? true : !modificar}
                                placeholder="00,00"
                                {...register("costo", {
                                    required: {
                                        value: true,
                                        message: "Ingrese precio del Producto"
                                    },
                                    validate: (value) => { //aqui evaluo con otra forma el patron, ya que debo hacer 2 validaciones
                                        const patron = /^\d+(,\d{1,2})?$/; //para que se respete el ingreso luego de la coma y luego
                                        if (!patron.test(value)) {            //convertir el texto en numero para erificar ques es mayor a cero
                                            return "Valor con 2 decimales luego de la ','";
                                        }
                                        // Reemplaza la coma por un punto y convierte a número
                                        const numericValue = parseFloat(value.replace(',', '.'));
                                        if (numericValue <= 0) {
                                            return "Ingrese un precio positivo";
                                        }
                                        return true;
                                    },
                                })}
                            />
                        </Tarjeta>


                    </div>
                    <div className="__columna_2">
                        <Tarjeta descripcion="Categoria" forid="categoria">
                            <Selector opciones={categorias.map(cat => ({ label: cat.nombre_categoria, value: cat.id_categoria }))}
                                id="categoria" deshabilitado={(permisoModificarStock && !permisoModificarProducto) ? true : !modificar}
                                defaultValue={autocompletar.id_categoria}
                                {...register("id_categoria")}>
                            </Selector>
                        </Tarjeta>
                        <Tarjeta descripcion="Marca" forid="marca">
                            <Selector opciones={marcas.map(marca => ({ label: marca.nombre_marca, value: marca.id_marca }))}
                                id="marca" deshabilitado={(permisoModificarStock && !permisoModificarProducto) ? true : !modificar}
                                defaultValue={autocompletar.id_marca}
                                {...register("id_marca")}
                            >
                            </Selector>
                        </Tarjeta>
                        <div className="__fila3">
                            <Tarjeta descripcion="Cantidad" forid="stock" mensajeError={errors.stock?.message}>
                                <Input
                                    tipo="number"
                                    id="stock"
                                    placeholder={cant}
                                    deshabilitado
                                    {...register("cantidad")}
                                > </Input>
                            </Tarjeta>
                            <Boton icono={restar} onClick={disminuyeCant} habilitado={modificar && permisoModificarStock} title="Disminuir Existnecias"></Boton>
                            <Boton icono={sumar} onClick={aumentaCant} habilitado={modificar && permisoModificarStock} title="Aumentar Existencias"></Boton>
                        </div>
                        {modCant && (
                            <div className="__mensaje_cantidad">
                                {cantidadModificada > 0
                                    ? `Cantidad aumentada: +${cantidadModificada}`
                                    : `Cantidad disminuida: ${cantidadModificada}`}
                            </div>
                        )}
                    </div>
                    <div className="__observacion">
                        <Tarjeta descripcion="Observacion" forid="observacion" mensajeError={errors.observaciones?.message}>
                            <textarea
                                id="obeservacion"
                                disabled={!modificar && permisoModificarStock}
                                className={`${modificar ? '__texto_habilitado' : '__texto_deshabilitado'}`}
                                {...register("observaciones", { required: { value: (cantidadModificada !== 0), message: "Ingrese motivo" } })}
                            > </textarea>
                        </Tarjeta>
                        <Tarjeta descripcion="Minima Alerta" forid="alerta" mensajeError={errors.stock?.message}>
                            <Input
                                tipo="number"
                                id="alerta"
                                deshabilitado={(permisoModificarStock && !permisoModificarProducto) ? true : !modificar}
                                {...register("alerta_minima", {
                                    required: {
                                        value: true,
                                        message: "Ingrese valor para alertar"
                                    },
                                    validate: (value) => {
                                        if (value >= 0) return true;
                                        else return "Ingrese una cantidad entre mayor a '0'";
                                    },
                                })}
                            > </Input>
                        </Tarjeta>
                    </div>
                </div>
                <div className="__formulario_footer_modificar">
                    {/* ✅ SECCIÓN DE FOTO ACTUALIZADA (igual que sucursal y combo) */}
                    <Tarjeta descripcion="Foto del Producto">
                        <div className="__contenedor_imagen_mod">
                            {nuevaImagen ? (
                                // Vista previa de nueva imagen seleccionada
                                <div className="__preview_imagen_mod" style={{ display: 'flex', alignItems: 'flex-start', gap: '20px' }}>
                                    <img src={nuevaImagen} alt="Nueva preview" className="__img_mod" />
                                    <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
                                        <Boton
                                            descripcion="Cancelar"
                                            onClick={cancelarCambioImagen}
                                            habilitado={modificar}
                                        />
                                    </div>
                                </div>
                            ) : (
                                // Imagen actual o placeholder
                                <div className="__preview_imagen_mod" style={{ display: 'flex', alignItems: 'flex-start', gap: '20px' }}>
                                    <img
                                        src={imagenEliminada ? no_encontrado : imagenActual}
                                        alt="Producto"
                                        className="__img_mod"
                                    />

                                    <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
                                        <Boton
                                            descripcion="Cambiar"
                                            onClick={activarCambioImagen}
                                            habilitado={modificar && !mostrarInputFile}
                                        />
                                        <Boton
                                            descripcion="Eliminar"
                                            onClick={eliminarImagenActual}
                                            habilitado={modificar && !imagenEliminada && imagenActual !== no_encontrado && !mostrarInputFile}
                                        />
                                    </div>
                                </div>
                            )}

                            {/* Input file solo cuando se hace clic en "Cambiar" */}
                            {modificar && mostrarInputFile && (
                                <div style={{ marginTop: "10px" }}>
                                    <input
                                        type="file"
                                        accept="image/*"
                                        onChange={manejarCambioImagen}
                                    />
                                    <div style={{ marginTop: "10px" }}>
                                        <Boton
                                            descripcion="Cancelar"
                                            onClick={cancelarCambioImagen}
                                            habilitado
                                        />
                                    </div>
                                </div>
                            )}
                        </div>
                    </Tarjeta>
                    <div className="__footer_botones_mod">
                        <Boton descripcion='Modificar' habilitado={(permisoModificarProducto || permisoModificarStock)} onClick={manejaModificacion}></Boton>
                        <Boton descripcion='Guardar' habilitado={modificar} submit></Boton>
                    </div>
                </div>
            </form>
        </>
    )
} 